/* MODULE dl02 · Bước 7 Đo lường · CAC, LTV và kinh tế đơn vị
   8 bài × 7 câu. Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'dl02', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:dl02-01', skill:'measure', read:'6 phút', t:'CAC trung bình 150.000đ đang giấu kênh nào?',
  situation:'Một shop mỹ phẩm online tháng này chi 60 triệu quảng cáo và có 400 khách mới, báo cáo ghi CAC 150.000đ — thấp hơn mức 200.000đ mà shop chịu được. Nhưng khi tách ra: Facebook 30 triệu mang về 250 khách, TikTok 20 triệu mang về 50 khách, Google 10 triệu mang về 100 khách.',
  concept:{ name:'CAC gộp và CAC theo kênh',
    body:'<b>CAC gộp</b> là tổng chi thu hút khách chia tổng khách mới — nó trả lời câu hỏi "cả cỗ máy có lời không". <b>CAC theo kênh</b> chia chi phí từng kênh cho khách mới của kênh đó — nó trả lời câu hỏi "tiền tiếp theo nên bỏ vào đâu". Con số gộp đẹp có thể là trung bình của một kênh rất rẻ và một kênh rất đắt. Quyết định phân bổ ngân sách luôn cần con số theo kênh.' },
  example:'Facebook: 30 triệu ÷ 250 = 120.000đ. Google: 10 triệu ÷ 100 = 100.000đ. TikTok: 20 triệu ÷ 50 = 400.000đ — gấp đôi mức chịu được. CAC gộp 150.000đ trông an toàn chỉ vì hai kênh rẻ gánh cho TikTok. Nếu cắt TikTok, shop mất 50 khách nhưng CAC gộp còn 40 triệu ÷ 350 ≈ 114.000đ.',
  takeaway:'CAC gộp cho biết cỗ máy có lời không; CAC theo kênh mới cho biết đồng tiếp theo nên đặt ở đâu.',
  apply:'Lấy chi phí và số khách mới của hai kênh bạn đang chạy. Tính CAC từng kênh, rồi nói trong 60 giây kênh nào đang được kênh kia gánh.',
  mistakes:['Thấy CAC gộp dưới ngưỡng là yên tâm giữ nguyên mọi kênh.','So CAC các kênh mà quên kênh đắt có thể mang khách khác hẳn (đơn to hơn, quay lại nhiều hơn).'],
  q:[
  { type:'mcq', stem:'Đoán trước: CAC gộp 150.000đ, thấp hơn ngưỡng 200.000đ. Có thể kết luận mọi kênh đều đang có lời không?',
    options:[{k:'a',t:'Có, vì trung bình thấp hơn ngưỡng nghĩa là từng kênh cũng thấp hơn ngưỡng'},{k:'b',t:'Không, vì trung bình có thể che một kênh vượt ngưỡng xa'},
             {k:'c',t:'Có, miễn là tổng số khách mới tháng này tăng so với tháng trước đó'},{k:'d',t:'Không, vì CAC gộp luôn thấp hơn CAC thật của mọi kênh'}],
    answer:'b', why:{a:'Trung bình thấp vẫn có thể gồm một kênh rất đắt được hai kênh rẻ bù lại.',
      b:'Đúng. Trung bình trộn kênh rẻ và kênh đắt; phải tách ra mới thấy.',
      c:'Số khách tăng không nói gì về giá của từng khách ở từng kênh.',
      d:'CAC gộp nằm giữa CAC các kênh, không thấp hơn tất cả.'} },
  { type:'mcq', stem:'Tháng sau shop có thêm 20 triệu. Bạn đặt số tiền này thế nào?',
    options:[{k:'a',t:'Chia đều ba kênh để giữ cơ cấu hiện tại cho công bằng và dễ so sánh'},{k:'b',t:'Dồn hết vào TikTok vì kênh đó ít khách nhất, còn nhiều dư địa để tăng'},
             {k:'c',t:'Thử tăng dần ở Google và Facebook, theo dõi CAC của phần tiền tăng thêm'},{k:'d',t:'Giữ nguyên, vì CAC gộp đang đẹp thì không cần động vào'}],
    answer:'c', why:{a:'Chia đều bỏ qua việc TikTok đang đắt gấp ba đến bốn lần hai kênh kia.',
      b:'Ít khách vì đắt, không phải vì còn dư địa; thêm tiền vào đó là mua khách giá 400.000đ.',
      c:'Đúng. Tiền mới đi về kênh có CAC thấp, và vẫn phải đo phần tăng thêm vì kênh rẻ có thể đắt dần.',
      d:'CAC gộp đẹp không trả lời được câu hỏi tiền mới nên đặt ở đâu.'} },
  { type:'calc', stem:'TikTok tiêu 20.000.000đ và mang về 50 khách mới. CAC của kênh TikTok là bao nhiêu đồng?',
    unit:'đ', ans:400000, tol:1, wrong:[[150000,'SAI_MAU_SO'],[50000,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['CAC kênh = chi phí của kênh ÷ khách mới của kênh.','20.000.000 ÷ 50 = <b>400.000đ</b>.'] },
  { type:'mcq', stem:'Khách từ TikTok có giá trị đơn trung bình gấp ba khách từ Google. Điều này thay đổi việc so CAC thế nào?',
    options:[{k:'a',t:'Phải so CAC với giá trị khách của từng kênh, không chỉ so CAC với nhau'},{k:'b',t:'Không thay đổi gì, CAC thấp hơn thì kênh đó luôn tốt hơn'},
             {k:'c',t:'Nên bỏ Google, vì khách từ Google mua ít hơn và kéo giá trị đơn trung bình của shop xuống'},{k:'d',t:'Nên cộng CAC hai kênh lại để có con số chung'}],
    answer:'a', why:{a:'Đúng. Kênh đắt vẫn có thể đáng nếu mỗi khách mang lại nhiều lãi hơn tương ứng.',
      b:'CAC chỉ là một nửa phép so; nửa kia là khách đó đáng bao nhiêu.',
      c:'Google vẫn rẻ và có lời; kết luận bỏ kênh nhảy quá xa từ một dữ kiện.',
      d:'Cộng lại là quay về CAC gộp, mất đúng thông tin cần để ra quyết định.'} },
  { type:'mcq', stem:'Một chuỗi trà sữa tính CAC bằng tổng chi marketing chia tổng khách mới cả chuỗi. Họ muốn biết có nên mở rộng quảng cáo Grab hay không. Vấn đề là gì?',
    options:[{k:'a',t:'Tổng chi marketing có cả lương nhân viên nên số liệu bị sai hoàn toàn'},{k:'b',t:'Grab là kênh bán hàng, không thể tính CAC cho một kênh bán hàng'},
             {k:'c',t:'Khách mới trà sữa khó đếm nên không nên dùng CAC cho ngành này'},{k:'d',t:'Con số gộp không cho biết khách từ Grab tốn bao nhiêu'}],
    answer:'d', why:{a:'Có thể gộp lương hay không là chuyện quy ước; vấn đề chính là độ phân giải.',
      b:'Quảng cáo trên Grab vẫn có chi phí và khách mới riêng, tính CAC được.',
      c:'Khó đếm thì đếm gần đúng; bỏ hẳn thước đo là mù.',
      d:'Đúng. Quyết định về một kênh cần CAC của kênh đó.'} },
  { type:'mcq', stem:'Sau khi cắt TikTok, CAC gộp giảm từ 150.000đ xuống khoảng 114.000đ. Điều gì cần kiểm tra trước khi ăn mừng?',
    options:[{k:'a',t:'Liệu có phải Facebook đang chạy tốt hơn hẳn tháng trước nhờ nội dung mới'},{k:'b',t:'Tổng khách mới giảm 50 người — doanh số có đủ bù không'},
             {k:'c',t:'Liệu TikTok có tính sai chi phí vì nền tảng thường báo thiếu số tiền đã tiêu'},{k:'d',t:'Liệu CAC gộp có giảm tiếp nếu cắt thêm cả Google'}],
    answer:'b', why:{a:'CAC gộp giảm ở đây là do bỏ kênh đắt, không phải do Facebook tốt lên.',
      b:'Đúng. CAC thấp hơn nhưng ít khách hơn; mục tiêu là lãi, không phải con số CAC đẹp.',
      c:'Chi phí lấy từ hoá đơn nền tảng, không có dấu hiệu báo sai.',
      d:'Google là kênh rẻ nhất; cắt nó làm CAC gộp tăng.'} },
  { type:'mcq', stem:'Câu nào mô tả đúng vai trò của hai loại CAC?',
    options:[{k:'a',t:'Gộp để báo cáo sếp, theo kênh cho người chạy quảng cáo'},{k:'b',t:'CAC theo kênh luôn chính xác hơn nên nên bỏ hẳn CAC gộp'},
             {k:'c',t:'Gộp để xem cả hệ thống có lời, theo kênh để phân bổ tiền'},{k:'d',t:'Hai con số phải bằng nhau, nếu lệch là dữ liệu có lỗi'}],
    answer:'c', why:{a:'Đây là phân vai theo người đọc, không theo câu hỏi mỗi con số trả lời.',
      b:'Vẫn cần con số gộp để biết cả cỗ máy có sống được không.',
      c:'Đúng. Mỗi con số trả lời một câu hỏi khác nhau.',
      d:'Chúng gần như luôn lệch nhau; độ lệch chính là thông tin.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:dl02-02', skill:'measure', read:'6 phút', t:'800 đơn tháng này — bao nhiêu là khách mới thật?',
  situation:'Một thương hiệu cà phê rang xay bán online chi 60 triệu quảng cáo trong tháng và có 800 đơn. Bạn đồng nghiệp tính CAC = 60 triệu ÷ 800 = 75.000đ và đề xuất tăng ngân sách gấp đôi. Nhìn danh sách đơn, 500 đơn đến từ số điện thoại đã từng mua trước đó.',
  concept:{ name:'Mẫu số của CAC là khách mới',
    body:'CAC đo chi phí để có <b>một khách chưa từng mua</b>. Mẫu số không phải số đơn, cũng không phải tổng khách mua trong tháng. Khách cũ quay lại phần lớn nhờ sản phẩm và chăm sóc, không nhờ quảng cáo thu hút. Đưa họ vào mẫu số làm CAC trông rẻ hơn thực tế, và khiến đội tăng chi vào quảng cáo thu hút với kỳ vọng sai. Cần một cách nhận diện khách mới nhất quán: số điện thoại, email hoặc tài khoản.' },
  example:'800 đơn − 500 đơn của khách cũ = 300 đơn của khách mới (giả sử mỗi khách mới đặt một đơn). CAC thật = 60 triệu ÷ 300 = 200.000đ, gấp gần ba lần con số 75.000đ. Nếu mỗi khách mới chỉ để lại 150.000đ lãi gộp trong vòng đời, tăng gấp đôi ngân sách là nhân đôi khoản lỗ.',
  takeaway:'Khách cũ quay lại không phải thành tích của quảng cáo thu hút — đừng để họ vào mẫu số CAC.',
  apply:'Mở danh sách đơn tháng gần nhất, lọc số điện thoại đã từng mua. Nói trong 60 giây: CAC tính trên khách mới khác bao nhiêu so với tính trên tổng đơn.',
  mistakes:['Lấy tổng đơn hoặc tổng khách mua trong tháng làm mẫu số.','Không có quy tắc nhận diện khách mới, mỗi tháng đếm một kiểu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: nếu tính lại CAC chỉ trên khách mới, con số sẽ thay đổi thế nào so với 75.000đ?',
    options:[{k:'a',t:'Giảm xuống, vì bớt khách cũ thì chi phí phân bổ cũng giảm theo'},{k:'b',t:'Gần như giữ nguyên, vì khách cũ và khách mới chi tiêu giống nhau'},
             {k:'c',t:'Tăng lên đáng kể, vì mẫu số nhỏ đi còn chi phí giữ nguyên'},{k:'d',t:'Không tính được, vì quảng cáo cũng chạm tới khách cũ'}],
    answer:'c', why:{a:'Chi phí quảng cáo đã tiêu hết, không giảm khi bớt mẫu số.',
      b:'Mức chi tiêu không liên quan; mẫu số đổi từ 800 xuống 300.',
      c:'Đúng. Cùng 60 triệu chia cho ít người hơn thì mỗi người đắt hơn.',
      d:'Vẫn tính được; quy ước chuẩn là chỉ đếm người mua lần đầu.'} },
  { type:'mcq', stem:'Đồng nghiệp đề xuất tăng gấp đôi ngân sách dựa trên CAC 75.000đ. Bạn làm gì?',
    options:[{k:'a',t:'Đồng ý, vì 75.000đ rõ ràng thấp và thương hiệu đang tăng trưởng nhanh qua từng tháng'},{k:'b',t:'Tính lại CAC trên 300 khách mới, so với lãi gộp mỗi khách rồi mới quyết'},
             {k:'c',t:'Từ chối, vì 500 đơn khách cũ chứng tỏ quảng cáo không có tác dụng'},{k:'d',t:'Tăng 50% thay vì gấp đôi để giảm rủi ro nhưng vẫn tận dụng đà'}],
    answer:'b', why:{a:'Con số 75.000đ sai mẫu số; quyết định trên nó là quyết định trên ảo giác.',
      b:'Đúng. Sửa mẫu số trước, rồi so với giá trị một khách mới.',
      c:'Khách cũ quay lại không chứng minh quảng cáo vô dụng; nó chỉ nằm ngoài phép tính CAC.',
      d:'Tăng ít hơn vẫn là tăng dựa trên con số sai.'} },
  { type:'calc', stem:'Chi 60.000.000đ quảng cáo, 800 đơn, trong đó 500 đơn của khách đã từng mua. Mỗi khách mới đặt một đơn. CAC thật là bao nhiêu đồng?',
    unit:'đ', ans:200000, tol:1, wrong:[[75000,'CAC_TINH_CA_KHACH_CU'],[120000,'SAI_MAU_SO']], errors:['CAC_TINH_CA_KHACH_CU'],
    steps:['Khách mới = 800 − 500 = 300.','CAC = 60.000.000 ÷ 300 = <b>200.000đ</b>.'] },
  { type:'mcq', stem:'Một khách mới đặt 3 đơn trong tháng đầu. Khi tính CAC, người này được đếm thế nào?',
    options:[{k:'a',t:'Là 1 khách mới, vì CAC tính trên người chứ không phải trên đơn'},{k:'b',t:'Là 3 khách, vì mỗi đơn là một lần chuyển đổi mà quảng cáo mang lại'},
             {k:'c',t:'Là 1 khách mới và 2 khách cũ'},{k:'d',t:'Không đếm, vì mua nhiều lần là khách trung thành'}],
    answer:'a', why:{a:'Đúng. Chi phí thu hút trả cho việc có được một người; các đơn sau là giá trị của người đó.',
      b:'Đếm theo đơn làm CAC thấp giả tạo, giống lỗi tính khách cũ.',
      c:'Cách chia này khiến một người vừa mới vừa cũ, làm rối cả CAC lẫn báo cáo khách quay lại.',
      d:'Người này vẫn là khách mới của tháng, chỉ có giá trị cao hơn.'} },
  { type:'mcq', stem:'Một tiệm bánh chỉ ghi nhận doanh thu, không lưu số điện thoại khách. Cách hợp lý nhất để có CAC tạm dùng là gì?',
    options:[{k:'a',t:'Lấy chi phí quảng cáo chia số hoá đơn, chấp nhận sai số vì không còn cách nào khác'},{k:'b',t:'Bỏ qua CAC, chỉ theo dõi doanh thu tổng vì tiệm nhỏ không cần đo'},
             {k:'c',t:'Dùng mã ưu đãi riêng cho khách lần đầu từ quảng cáo và đếm mã'},{k:'d',t:'Hỏi nhân viên đoán tỉ lệ khách mới mỗi ngày rồi nhân với số hoá đơn'}],
    answer:'c', why:{a:'Chia cho số hoá đơn là lặp lại đúng lỗi tính cả khách cũ.',
      b:'Không đo thì không biết tiền quảng cáo có lời không.',
      c:'Đúng. Mã dành riêng cho lần mua đầu cho một cách đếm khách mới nhất quán, dù chưa hoàn hảo.',
      d:'Ước đoán cảm tính khó lặp lại và không kiểm tra được.'} },
  { type:'mcq', stem:'Tháng sau, CAC tính đúng giảm từ 200.000đ xuống 160.000đ, trong khi tỉ lệ khách cũ trong tổng đơn tăng. Đọc thế nào?',
    options:[{k:'a',t:'Khách cũ tăng nên chắc chắn CAC giảm là nhờ khách cũ đem về'},{k:'b',t:'Là dấu hiệu dữ liệu sai, vì CAC không thể giảm khi khách cũ tăng'},
             {k:'c',t:'Quảng cáo đang tệ đi vì phần lớn đơn đến từ khách cũ chứ không phải khách mới'},{k:'d',t:'Hai chỉ số độc lập: thu hút rẻ hơn, và giữ chân cũng tốt lên'}],
    answer:'d', why:{a:'Khách cũ không nằm trong mẫu số CAC nên không làm CAC giảm.',
      b:'Không có mâu thuẫn; hai con số đo hai việc khác nhau.',
      c:'Tỉ lệ khách cũ tăng có thể do giữ chân tốt, không có nghĩa quảng cáo tệ đi.',
      d:'Đúng. Khi mẫu số được tách đúng, hai hoạt động được đọc riêng.'} },
  { type:'mcq', stem:'Vì sao gộp khách cũ vào mẫu số CAC gây hại cho quyết định ngân sách?',
    options:[{k:'a',t:'Làm quảng cáo thu hút trông rẻ hơn thật, dẫn tới chi quá tay'},{k:'b',t:'Vì khách cũ thường chi tiêu ít hơn nên kéo giá trị đơn trung bình xuống'},
             {k:'c',t:'Vì báo cáo khó trình bày hơn'},{k:'d',t:'Vì nền tảng quảng cáo sẽ phạt tài khoản khi tính sai'}],
    answer:'a', why:{a:'Đúng. Con số rẻ giả tạo khuyến khích tăng chi vào đúng chỗ đang đắt.',
      b:'Mức chi tiêu của khách cũ không phải vấn đề ở đây.',
      c:'Độ dài báo cáo không liên quan; cái hại là quyết định sai.',
      d:'Nền tảng không biết và không quan tâm bạn tính CAC thế nào.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:dl02-03', skill:'measure', read:'7 phút', t:'LTV 1,2 triệu mà vẫn lỗ khi CAC 500.000đ?',
  situation:'Shop hạt dinh dưỡng bán đơn trung bình 300.000đ, khách mua trung bình 4 lần trong vòng đời. Chủ shop tính LTV = 1,2 triệu và yên tâm chạy quảng cáo với CAC 500.000đ vì "gấp hơn hai lần". Cuối năm, doanh thu tăng nhưng tài khoản không dày lên. Biên lãi gộp của shop là 40%.',
  concept:{ name:'LTV tính trên lãi gộp',
    body:'LTV dùng để so với CAC, nên phải cùng loại tiền: tiền còn lại để trả chi phí thu hút. Doanh thu chưa trừ giá vốn hàng bán thì không phải tiền đó. Cách an toàn là <b>LTV = giá trị đơn × số lần mua × biên lãi gộp</b>. Nếu mỗi đơn còn tốn ship, phí sàn, thì dùng lãi sau các chi phí biến đổi đó. So CAC với LTV doanh thu gần như luôn khiến quảng cáo trông có lời hơn thật.' },
  example:'LTV lãi gộp = 300.000 × 4 × 40% = 480.000đ. CAC 500.000đ lớn hơn 480.000đ: mỗi khách mới thu hút xong là lỗ 20.000đ, chưa tính chi phí vận hành. Tỉ lệ "gấp 2,4 lần" hoàn toàn đến từ việc so doanh thu với chi phí. Để có lời, shop cần CAC dưới 480.000đ khá xa, hoặc tăng số lần mua.',
  takeaway:'CAC trả bằng lãi, nên LTV phải tính bằng lãi — không bằng doanh thu.',
  apply:'Lấy giá trị đơn, số lần mua và biên lãi gộp của một sản phẩm bạn biết. Tính LTV hai cách và nói trong 60 giây khoảng chênh đó nguy hiểm thế nào khi so với CAC.',
  mistakes:['Nhân giá trị đơn với số lần mua rồi so thẳng với CAC.','Dùng biên lãi gộp nhưng quên phí sàn, ship mà shop chịu trên mỗi đơn.'],
  q:[
  { type:'mcq', stem:'Đoán trước: shop có LTV 1,2 triệu và CAC 500.000đ. Vì sao tài khoản vẫn không dày lên?',
    options:[{k:'a',t:'Vì khách chưa mua đủ 4 lần trong năm đầu nên tiền về chậm hơn dự kiến ban đầu'},{k:'b',t:'Vì 1,2 triệu là doanh thu; phần lãi thật còn thấp hơn CAC'},
             {k:'c',t:'Vì CAC 500.000đ bị nền tảng tính sai, thực tế còn cao hơn nhiều'},{k:'d',t:'Vì shop chưa tính thuế nên lãi bị trừ mất một nửa'}],
    answer:'b', why:{a:'Tiền về chậm có thể đúng, nhưng kể cả khi đủ 4 lần shop vẫn lỗ.',
      b:'Đúng. 40% của 1,2 triệu là 480.000đ, thấp hơn CAC.',
      c:'Không có dữ kiện cho thấy CAC sai.',
      d:'Thuế có thể có, nhưng lỗ đã xuất hiện ngay ở tầng lãi gộp.'} },
  { type:'mcq', stem:'Bạn được giao sửa bảng tính LTV của shop. Bạn sửa công thức thành gì?',
    options:[{k:'a',t:'Giá trị đơn × số lần mua, rồi trừ đi CAC để ra phần lãi của mỗi khách'},{k:'b',t:'Giá trị đơn × số lần mua × 2, vì khách còn giới thiệu thêm bạn bè'},
             {k:'c',t:'Chỉ lấy giá trị đơn đầu tiên, vì các lần mua sau không chắc xảy ra'},{k:'d',t:'Giá trị đơn × số lần mua × biên lãi gộp, rồi mới so CAC'}],
    answer:'d', why:{a:'Trừ CAC từ doanh thu vẫn bỏ qua giá vốn; khoản lãi nhìn thấy là ảo.',
      b:'Nhân đôi không có căn cứ; giới thiệu phải đo riêng.',
      c:'Bỏ hết các lần mua sau là quá bi quan và sai với dữ liệu 4 lần mua.',
      d:'Đúng. Đưa LTV về đơn vị lãi để so được với CAC.'} },
  { type:'calc', stem:'Đơn trung bình 300.000đ, mua 4 lần trong vòng đời, biên lãi gộp 40%. LTV tính trên lãi gộp là bao nhiêu đồng?',
    unit:'đ', ans:480000, tol:1, wrong:[[1200000,'LTV_TINH_DOANH_THU'],[120000,'SAI_TINH_TOAN']], errors:['LTV_TINH_DOANH_THU'],
    steps:['Doanh thu vòng đời = 300.000 × 4 = 1.200.000đ.','LTV lãi gộp = 1.200.000 × 40% = <b>480.000đ</b>.'] },
  { type:'mcq', stem:'Shop hạt muốn có lời với CAC 500.000đ. Hướng nào đi đúng vào gốc vấn đề?',
    options:[{k:'a',t:'Tăng số lần mua hoặc biên lãi để LTV lãi gộp vượt xa CAC'},{k:'b',t:'Tăng ngân sách để có nhiều khách hơn, lời sẽ đến từ quy mô lớn'},
             {k:'c',t:'Giảm giá 20% để khách mua nhiều lần hơn trong vòng đời'},{k:'d',t:'Đổi sang báo cáo LTV theo doanh thu cho ban giám đốc dễ đọc và đỡ phải giải thích dài'}],
    answer:'a', why:{a:'Đúng. Hoặc giảm CAC, hoặc tăng lãi mỗi khách; đây là vế thứ hai.',
      b:'Mỗi khách đang lỗ; thêm khách là thêm lỗ.',
      c:'Giảm 20% giá khi biên chỉ 40% là cắt đi một nửa lãi mỗi đơn; số lần mua phải tăng rất mạnh mới bù.',
      d:'Đổi cách báo cáo không đổi tiền trong tài khoản.'} },
  { type:'calc', stem:'Một app học tiếng Anh thu 200.000đ/tháng, khách dùng trung bình 6 tháng. Chi phí máy chủ, cổng thanh toán và giáo viên chấm bài chiếm 55% doanh thu. LTV tính trên lãi gộp là bao nhiêu đồng?',
    unit:'đ', ans:540000, tol:1, wrong:[[1200000,'LTV_TINH_DOANH_THU'],[660000,'NHAM_GIA_VON']], errors:['LTV_TINH_DOANH_THU'],
    steps:['Doanh thu vòng đời = 200.000 × 6 = 1.200.000đ.','Biên lãi gộp = 100% − 55% = 45%.','LTV = 1.200.000 × 45% = <b>540.000đ</b>.'] },
  { type:'mcq', stem:'Với shop bán trên sàn, vì sao nên trừ cả phí sàn và ship shop chịu khi tính LTV?',
    options:[{k:'a',t:'Vì sàn yêu cầu người bán báo cáo LTV theo cách tính của sàn'},{k:'b',t:'Vì đó là chi phí cố định cần phân bổ'},
             {k:'c',t:'Vì chúng phát sinh theo từng đơn, ăn vào tiền trả được CAC'},{k:'d',t:'Vì chúng làm doanh thu thấp đi nên LTV nhìn khiêm tốn hơn'}],
    answer:'c', why:{a:'Sàn không đặt ra quy định này; đây là chuyện bạn tự biết mình lời hay lỗ.',
      b:'Phí sàn và ship là chi phí biến đổi theo đơn, không phải cố định.',
      c:'Đúng. Mỗi đơn đi kèm các khoản này; bỏ qua là LTV bị thổi phồng.',
      d:'Mục đích không phải trông khiêm tốn mà là đúng loại tiền.'} },
  { type:'mcq', stem:'Câu nào đúng về việc so LTV với CAC?',
    options:[{k:'a',t:'LTV doanh thu so với CAC vẫn ổn nếu mình tự nhớ trừ hao khoảng một nửa'},{k:'b',t:'Hai số phải cùng đơn vị tiền: lãi còn lại để trả chi phí thu hút'},
             {k:'c',t:'LTV nên tính trên lợi nhuận ròng'},{k:'d',t:'Chỉ cần LTV lớn hơn CAC một đồng là có lời bền vững'}],
    answer:'b', why:{a:'"Trừ hao một nửa" là đoán; biên lãi mỗi ngành khác nhau rất xa.',
      b:'Đúng. So táo với táo: lãi mỗi khách với chi phí có khách đó.',
      c:'Chi phí cố định xử lý ở tầng khác; nhồi hết vào LTV khiến LTV khó dùng cho quyết định kênh.',
      d:'Hơn một đồng không chừa gì cho chi phí vận hành và rủi ro.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:dl02-04', skill:'measure', read:'6 phút', t:'Tỉ lệ LTV/CAC bằng 3 thì nên làm gì tiếp?',
  situation:'Một thương hiệu thực phẩm sạch giao tận nhà có LTV lãi gộp 900.000đ và CAC 300.000đ. Giám đốc hỏi: "Tỉ lệ 3 là tốt hay xấu? Có nên tăng quảng cáo không?" Một thành viên khác đưa ra con số 7,5 vì chia doanh thu vòng đời 2,25 triệu cho CAC.',
  concept:{ name:'Tỉ lệ LTV/CAC',
    body:'Tỉ lệ này cho biết mỗi đồng bỏ ra thu hút khách mang về bao nhiêu đồng lãi gộp. <b>Dưới 1</b>: mỗi khách mới làm mất tiền. <b>Quanh 1–2</b>: có lãi gộp nhưng mỏng, dễ bị chi phí vận hành và khách rời sớm ăn hết. Nhiều doanh nghiệp dùng <b>khoảng 3</b> làm mốc tham chiếu. Tỉ lệ <b>rất cao</b> không chỉ là tin vui — có thể doanh nghiệp đang chi quá ít và bỏ lỡ khách mà đối thủ sẽ lấy. Mốc phù hợp tuỳ ngành và tuỳ vốn.' },
  example:'900.000 ÷ 300.000 = 3: mỗi đồng thu hút mang về ba đồng lãi gộp. Con số 7,5 là doanh thu chia CAC, trông rất hấp dẫn nhưng sai loại tiền. Với tỉ lệ 3, thương hiệu có dư địa để tăng quảng cáo từng bước, miễn là theo dõi CAC của phần tăng thêm và kiểm tra khách mới có giữ được như khách cũ không.',
  takeaway:'LTV/CAC cho biết mỗi đồng thu hút mang về bao nhiêu đồng lãi — quá thấp là lỗ, quá cao có thể là đang chi quá ít.',
  apply:'Tính LTV/CAC cho một sản phẩm bạn biết. Nói trong 60 giây: con số đó bảo bạn nên chi thêm, giữ nguyên hay dừng.',
  mistakes:['Dùng LTV doanh thu nên tỉ lệ trông cao gấp mấy lần thật.','Thấy tỉ lệ rất cao là giữ nguyên ngân sách, không nhận ra mình đang chi quá ít.'],
  q:[
  { type:'mcq', stem:'Đoán trước: tỉ lệ LTV/CAC bằng 8 (tính đúng trên lãi gộp) có nghĩa gì?',
    options:[{k:'a',t:'Hoàn hảo, doanh nghiệp không cần thay đổi gì trong chiến lược'},{k:'b',t:'Chắc chắn dữ liệu có lỗi vì tỉ lệ không thể cao đến vậy'},
             {k:'c',t:'Có lời tốt, và có thể đang chi quá ít cho thu hút'},{k:'d',t:'Nên giảm giá bán để tỉ lệ về gần 3 cho giống với các doanh nghiệp khác trong ngành'}],
    answer:'c', why:{a:'Tỉ lệ rất cao thường là tín hiệu có thể tăng tốc.',
      b:'Tỉ lệ cao hiếm nhưng hoàn toàn có thể với kênh rẻ hoặc khách rất trung thành.',
      c:'Đúng. Lời tốt, nhưng cần hỏi: có bỏ lỡ khách vì chi quá dè dặt không?',
      d:'Không có lý do tự hạ lãi để khớp một mốc tham chiếu.'} },
  { type:'mcq', stem:'Với tỉ lệ 3 tính đúng, giám đốc hỏi có nên tăng quảng cáo. Bạn đề xuất gì?',
    options:[{k:'a',t:'Tăng ngân sách từng bước, đo CAC của phần tiền tăng thêm'},{k:'b',t:'Tăng gấp ba ngân sách ngay lập tức vì mỗi đồng mang về ba đồng lãi gộp cho công ty'},
             {k:'c',t:'Giữ nguyên, vì 3 chỉ vừa đủ mốc tham chiếu, chưa an toàn'},{k:'d',t:'Chuyển sang dùng tỉ lệ 7,5 để thuyết phục giám đốc chi mạnh hơn'}],
    answer:'a', why:{a:'Đúng. Tỉ lệ 3 cho phép thử tăng, nhưng khách thêm vào thường đắt hơn khách hiện tại.',
      b:'Tỉ lệ đo trên mức chi hiện tại; tăng gấp ba thì CAC gần như chắc chắn thay đổi.',
      c:'3 là mức lành mạnh; đứng yên có thể nhường khách cho đối thủ.',
      d:'7,5 sai loại tiền; dùng nó là tự lừa mình và lừa sếp.'} },
  { type:'calc', stem:'LTV lãi gộp 900.000đ, CAC 300.000đ. Tỉ lệ LTV/CAC là bao nhiêu?',
    unit:'lần', ans:3, tol:0.01, wrong:[[7.5,'LTV_TINH_DOANH_THU'],[0.33,'SAI_MAU_SO']], errors:['LTV_TINH_DOANH_THU'],
    steps:['Tỉ lệ = LTV ÷ CAC.','900.000 ÷ 300.000 = <b>3</b>.'] },
  { type:'mcq', stem:'Một shop thời trang có LTV/CAC = 0,8. Điều nào mô tả đúng tình hình?',
    options:[{k:'a',t:'Vẫn ổn, vì chỉ cần gần 1 là hoà vốn và thương hiệu đang được xây dựng dần'},{k:'b',t:'Chỉ đáng lo khi xuống dưới 0,5'},
             {k:'c',t:'Shop đang lời 80% trên mỗi khách mới'},{k:'d',t:'Mỗi khách mới mang về ít lãi hơn chi phí có khách đó'}],
    answer:'d', why:{a:'Dưới 1 là lỗ trên từng khách, trước cả chi phí vận hành; "xây thương hiệu" không trả được hoá đơn.',
      b:'Không có mốc 0,5; dưới 1 đã là lỗ.',
      c:'0,8 là tỉ lệ, không phải biên lời; nó nghĩa là thu về 80 đồng cho mỗi 100 đồng bỏ ra.',
      d:'Đúng. Mỗi 100 đồng thu hút chỉ mang về 80 đồng lãi gộp.'} },
  { type:'mcq', stem:'Hai kênh cùng có tỉ lệ 3. Kênh A khách mua đều trong 3 tháng, kênh B khách mua rải trong 3 năm. Điều gì khác nhau?',
    options:[{k:'a',t:'Không khác gì, vì tỉ lệ bằng nhau thì giá trị hai kênh bằng nhau'},{k:'b',t:'Kênh A hoàn vốn nhanh hơn nhiều, ít rủi ro dòng tiền hơn'},
             {k:'c',t:'Kênh B tốt hơn vì khách gắn bó lâu'},{k:'d',t:'Kênh A có CAC chắc chắn thấp hơn kênh B'}],
    answer:'b', why:{a:'Tỉ lệ bỏ qua thời gian; tiền về sau 3 năm rủi ro hơn và giam vốn lâu hơn.',
      b:'Đúng. Cùng tỉ lệ, nhưng tiền về sớm thì quay vòng được sớm.',
      c:'Gắn bó lâu là tốt, nhưng cùng tổng lãi mà về chậm hơn thì kém hơn về dòng tiền.',
      d:'Dữ kiện không nói gì về CAC tuyệt đối của hai kênh.'} },
  { type:'mcq', stem:'Vì sao mốc "khoảng 3" không nên áp máy móc cho mọi doanh nghiệp?',
    options:[{k:'a',t:'Vì mốc 3 chỉ đúng cho doanh nghiệp nước ngoài có vốn lớn'},{k:'b',t:'Vì tỉ lệ LTV/CAC thay đổi hằng ngày nên không có mốc nào dùng được'},
             {k:'c',t:'Vì biên lãi, chi phí vận hành và vốn mỗi nơi khác nhau'},{k:'d',t:'Vì luật mỗi nước quy định mốc riêng'}],
    answer:'c', why:{a:'Mốc là quy ước tham chiếu, không gắn với quốc tịch.',
      b:'Tỉ lệ biến động nhưng vẫn đo và so được theo tháng, theo quý.',
      c:'Đúng. Doanh nghiệp chi phí vận hành cao cần tỉ lệ cao hơn; nơi có vốn dài hạn có thể chấp nhận thấp hơn tạm thời.',
      d:'Đây là chỉ số quản trị, không phải quy định pháp lý.'} },
  { type:'mcq', stem:'Một bạn tính LTV/CAC trên toàn bộ khách, kể cả khách đến tự nhiên không qua quảng cáo. Tỉ lệ đó bị lệch thế nào?',
    options:[{k:'a',t:'Thấp hơn thật, vì khách tự nhiên kéo LTV xuống'},{k:'b',t:'Cao hơn thật, vì khách tự nhiên được chia chi phí'},
             {k:'c',t:'Không lệch, vì LTV tính trên người nên nguồn khách không quan trọng'},{k:'d',t:'Lệch ngẫu nhiên, lên hay xuống tuỳ tháng'}],
    answer:'b', why:{a:'Khách tự nhiên thường không mua ít hơn; và vấn đề chính là họ làm CAC thấp đi.',
      b:'Đúng. Khách tự nhiên vào mẫu số làm CAC rẻ giả, tỉ lệ đẹp giả.',
      c:'Nguồn khách quyết định họ có tốn chi phí thu hút hay không.',
      d:'Hướng lệch có hệ thống: luôn làm quảng cáo trông tốt hơn.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:dl02-05', skill:'measure', read:'7 phút', t:'Bán gói cà phê tháng hay bán lẻ từng túi: bao lâu thì hoàn vốn CAC?',
  situation:'Một xưởng rang cà phê ở Đà Lạt có CAC 400.000đ. Họ đang cân nhắc hai mô hình. Bán lẻ: túi 250.000đ, lãi gộp 40%, khách trung bình mua lại mỗi 2 tháng. Gói đăng ký: 250.000đ mỗi tháng giao tận nhà, cùng biên lãi. Vốn lưu động của xưởng chỉ đủ chờ tối đa 6 tháng.',
  concept:{ name:'Thời gian hoàn vốn CAC (payback)',
    body:'<b>Payback = CAC ÷ lãi gộp mỗi tháng từ một khách</b>. Nó trả lời: bỏ tiền ra có khách hôm nay, bao lâu thì lấy lại? Với doanh nghiệp vốn mỏng, câu hỏi này quan trọng không kém LTV/CAC: LTV cao mà hoàn vốn sau 18 tháng thì có thể cạn tiền trước khi kịp lời. Mô hình đăng ký thường rút ngắn payback vì tiền về đều và dày hơn — với điều kiện khách không huỷ sớm.' },
  example:'Lãi gộp mỗi túi = 250.000 × 40% = 100.000đ. Gói tháng: 100.000đ mỗi tháng → hoàn vốn 400.000 ÷ 100.000 = 4 tháng, nằm trong ngưỡng 6 tháng. Bán lẻ: trung bình 50.000đ mỗi tháng → 8 tháng, vượt ngưỡng. Nếu khách gói tháng huỷ sau 3 tháng, xưởng vẫn chưa hoàn vốn, nên tỉ lệ giữ chân ba tháng đầu là con số cần theo dõi sát.',
  takeaway:'LTV nói bạn lời bao nhiêu, payback nói bạn phải chờ bao lâu — vốn mỏng thì câu thứ hai quyết định.',
  apply:'Lấy CAC và lãi gộp mỗi tháng từ một khách của một mô hình bạn biết. Tính payback và nói trong 60 giây doanh nghiệp có đủ vốn để chờ không.',
  mistakes:['Chia CAC cho doanh thu mỗi tháng thay vì lãi gộp, ra payback ngắn giả.','Giả định mọi khách đăng ký ở lại đủ lâu, không kiểm tra tỉ lệ huỷ sớm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: cùng giá, cùng biên lãi, cùng CAC. Mô hình nào hoàn vốn nhanh hơn?',
    options:[{k:'a',t:'Bán lẻ, vì khách tự quyết mua nên họ hài lòng hơn và ít đòi hỏi'},{k:'b',t:'Như nhau, vì giá và biên lãi giống nhau thì thời gian hoàn vốn giống nhau'},
             {k:'c',t:'Bán lẻ, vì không tốn chi phí quản lý gói và giao định kỳ'},{k:'d',t:'Gói tháng, vì lãi gộp về mỗi tháng thay vì mỗi hai tháng'}],
    answer:'d', why:{a:'Hài lòng không làm tiền về nhanh hơn.',
      b:'Tần suất mua khác nhau thì lãi mỗi tháng khác nhau.',
      c:'Chi phí quản lý có thể có, nhưng không đảo ngược chênh lệch gấp đôi về tần suất.',
      d:'Đúng. Tiền về dày gấp đôi nên thời gian hoàn vốn ngắn một nửa.'} },
  { type:'mcq', stem:'Vốn của xưởng chỉ đủ chờ 6 tháng. Bạn chọn thế nào?',
    options:[{k:'a',t:'Đẩy gói tháng làm chính, theo dõi sát tỉ lệ huỷ trong 3 tháng đầu'},{k:'b',t:'Giữ bán lẻ vì quen thuộc, tăng ngân sách quảng cáo để có nhiều khách hơn bù lại'},
             {k:'c',t:'Làm gói tháng nhưng giảm giá 30% để nhiều người đăng ký hơn'},{k:'d',t:'Chọn bán lẻ vì LTV dài hạn của hai mô hình như nhau'}],
    answer:'a', why:{a:'Đúng. 4 tháng nằm trong ngưỡng vốn; rủi ro chính là khách huỷ trước tháng thứ 4.',
      b:'Bán lẻ hoàn vốn 8 tháng; thêm khách là thêm tiền bị giam lâu hơn khả năng chờ.',
      c:'Giảm 30% khi biên chỉ 40% làm lãi mỗi tháng còn rất mỏng, payback kéo dài gấp nhiều lần.',
      d:'LTV giống nhau không cứu được doanh nghiệp hết tiền giữa chừng.'} },
  { type:'calc', stem:'CAC 400.000đ, gói tháng 250.000đ, biên lãi gộp 40%. Thời gian hoàn vốn CAC là bao nhiêu tháng?',
    unit:'tháng', ans:4, tol:0.01, wrong:[[1.6,'LTV_TINH_DOANH_THU'],[10,'SAI_TINH_TOAN']], errors:['LTV_TINH_DOANH_THU'],
    steps:['Lãi gộp mỗi tháng = 250.000 × 40% = 100.000đ.','Payback = 400.000 ÷ 100.000 = <b>4 tháng</b>.'] },
  { type:'calc', stem:'Bán lẻ: túi 250.000đ, biên lãi gộp 40%, khách mua lại trung bình mỗi 2 tháng. CAC 400.000đ. Hoàn vốn sau bao nhiêu tháng?',
    unit:'tháng', ans:8, tol:0.01, wrong:[[4,'NGUOC_TAN_SUAT'],[3.2,'LTV_TINH_DOANH_THU']], errors:['NGUOC_TAN_SUAT'],
    steps:['Lãi gộp mỗi túi = 100.000đ; mỗi 2 tháng một túi → 50.000đ mỗi tháng.','Payback = 400.000 ÷ 50.000 = <b>8 tháng</b>.'] },
  { type:'mcq', stem:'Sau 3 tháng, 40% khách gói tháng đã huỷ. Điều này ảnh hưởng gì?',
    options:[{k:'a',t:'Không sao, vì 60% khách còn lại vẫn trả tiền đều đặn mỗi tháng như cam kết ban đầu'},{k:'b',t:'Nhóm huỷ chưa hoàn vốn, payback thực của cả nhóm dài hơn 4 tháng'},
             {k:'c',t:'Payback rút ngắn vì xưởng đỡ tốn chi phí giao hàng'},{k:'d',t:'Chỉ ảnh hưởng LTV, không ảnh hưởng thời gian hoàn vốn'}],
    answer:'b', why:{a:'40% khách chỉ trả 3 tháng, tức 300.000đ lãi cho 400.000đ CAC — lỗ trên nhóm này.',
      b:'Đúng. Tính trung bình cả nhóm, tiền về chậm hơn giả định mọi người ở lại.',
      c:'Giảm chi phí giao không bù được khoản lãi mất đi.',
      d:'Huỷ sớm làm lãi mỗi tháng của nhóm giảm, kéo dài payback.'} },
  { type:'mcq', stem:'Một bạn tính payback bằng CAC ÷ doanh thu tháng và ra 1,6 tháng. Rủi ro là gì?',
    options:[{k:'a',t:'Chỉ là một cách tính khác cho gọn, kết quả tương đương'},{k:'b',t:'Payback bị tính dài hơn thật, khiến xưởng quá thận trọng'},
             {k:'c',t:'Hoàn vốn trông nhanh gấp 2,5 lần thật, dễ chi quá sức vốn'},{k:'d',t:'Chỉ sai khi biên lãi dưới 20%'}],
    answer:'c', why:{a:'Doanh thu chưa trừ giá vốn, không phải tiền trả lại được CAC.',
      b:'Ngược lại: chia cho số lớn hơn thì ra thời gian ngắn hơn.',
      c:'Đúng. 1,6 tháng so với 4 tháng thật; kế hoạch vốn dựa trên đó sẽ hụt.',
      d:'Biên 40% vẫn làm sai 2,5 lần; không có ngưỡng an toàn nào.'} },
  { type:'mcq', stem:'Một chuỗi gym có LTV/CAC = 4 nhưng payback 20 tháng. Họ nên lo điều gì nhất?',
    options:[{k:'a',t:'Không cần lo, tỉ lệ 4 là rất tốt so với mốc tham chiếu thông thường'},{k:'b',t:'CAC quá thấp, nên tăng giá gói để cân bằng lại'},
             {k:'c',t:'LTV bị tính sai vì payback dài thì tỉ lệ không thể đạt 4'},{k:'d',t:'Dòng tiền: mở rộng nhanh có thể cạn vốn trước khi thu hồi'}],
    answer:'d', why:{a:'Tỉ lệ tốt nhưng tiền về quá chậm; tăng trưởng nhanh sẽ đốt vốn.',
      b:'Không có dữ kiện CAC thấp; payback dài cho thấy điều ngược lại.',
      c:'Hoàn toàn có thể: khách ở rất lâu nên tổng lãi cao, nhưng mỗi tháng về ít.',
      d:'Đúng. Mỗi khách mới giam tiền gần hai năm; tăng nhanh cần vốn dày.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:dl02-06', skill:'measure', read:'7 phút', t:'Đơn 250.000đ trên sàn: thật sự còn lại bao nhiêu?',
  situation:'Một shop bán đồ gốm trên Shopee, đơn trung bình 250.000đ. Giá vốn 100.000đ, shop chịu ship 20.000đ, phí sàn khoảng 12% giá bán, hộp và chống sốc 5.000đ. Quảng cáo trong sàn tính ra khoảng 60.000đ mỗi đơn. Ngoài ra, shop thuê kho và trả lương một nhân viên đóng gói, tổng 14 triệu mỗi tháng.',
  concept:{ name:'Kinh tế đơn vị của một đơn hàng',
    body:'Kinh tế đơn vị là xem <b>một đơn</b> có lời không trước khi hỏi cả tháng có lời không. Đi từ trên xuống: giá bán − giá vốn − các chi phí biến đổi theo đơn (ship shop chịu, phí sàn, đóng gói) − chi phí quảng cáo mỗi đơn = <b>đóng góp mỗi đơn</b>. Phần đóng góp này phải gánh chi phí cố định như thuê kho, lương. Số đơn cần để hoà vốn tháng = chi phí cố định ÷ đóng góp mỗi đơn.' },
  example:'Phí sàn = 250.000 × 12% = 30.000đ. Đóng góp = 250.000 − 100.000 − 20.000 − 30.000 − 5.000 − 60.000 = 35.000đ. Để trả 14 triệu chi phí cố định, shop cần 14.000.000 ÷ 35.000 = 400 đơn mỗi tháng. Nếu chỉ nhìn "250.000 − 100.000 = 150.000đ lãi", chủ shop sẽ tưởng 100 đơn là dư sức.',
  takeaway:'Một đơn chỉ có lời khi giá bán vượt giá vốn, mọi chi phí theo đơn và phần quảng cáo của chính đơn đó.',
  apply:'Viết ra năm dòng chi phí của một đơn hàng bạn biết (giá vốn, ship, phí sàn, đóng gói, quảng cáo). Nói trong 60 giây mỗi đơn đóng góp bao nhiêu và cần bao nhiêu đơn để hoà vốn tháng.',
  mistakes:['Lấy giá bán trừ giá vốn và gọi đó là lãi mỗi đơn.','Tính đóng góp mỗi đơn đúng nhưng quên chi phí cố định hàng tháng phải gánh.'],
  q:[
  { type:'mcq', stem:'Đoán trước: sau giá vốn 100.000đ, đơn 250.000đ còn lại khoảng bao nhiêu khi trừ hết các chi phí theo đơn và quảng cáo?',
    options:[{k:'a',t:'Khoảng 150.000đ, vì các chi phí khác nhỏ, không đáng kể so với giá vốn'},{k:'b',t:'Khoảng 120.000đ, chỉ cần trừ thêm tiền ship shop chịu'},
             {k:'c',t:'Khoảng 35.000đ — phần lớn khoảng chênh bị chi phí theo đơn ăn mất'},{k:'d',t:'Âm, vì bán trên sàn không bao giờ có lời'}],
    answer:'c', why:{a:'Ship, phí sàn, đóng gói và quảng cáo cộng lại 115.000đ, không nhỏ chút nào.',
      b:'Còn phí sàn, đóng gói và quảng cáo chưa trừ.',
      c:'Đúng. 150.000đ chênh lệch còn 35.000đ sau các chi phí theo đơn.',
      d:'Đơn này vẫn đóng góp dương; câu hỏi là có đủ số đơn để gánh chi phí cố định không.'} },
  { type:'mcq', stem:'Shop đang bán khoảng 250 đơn mỗi tháng. Bạn đề xuất gì trước tiên?',
    options:[{k:'a',t:'Tăng quảng cáo gấp đôi để đạt 400 đơn, vì mỗi đơn đều đóng góp dương'},{k:'b',t:'Tăng đóng góp mỗi đơn: gộp đơn to hơn hoặc giảm quảng cáo mỗi đơn'},
             {k:'c',t:'Chuyển toàn bộ sang website riêng để khỏi mất phí sàn 12% cho mỗi đơn hàng bán ra'},{k:'d',t:'Cắt nhân viên đóng gói để chi phí cố định về 0'}],
    answer:'b', why:{a:'Tăng gấp đôi quảng cáo thường làm quảng cáo mỗi đơn đắt lên, có thể xoá sạch 35.000đ đóng góp.',
      b:'Đúng. Với 250 đơn × 35.000đ = 8,75 triệu, còn thiếu 5,25 triệu; nâng đóng góp mỗi đơn là đòn bẩy trực tiếp.',
      c:'Website riêng tiết kiệm phí sàn nhưng phải tự kéo khách, chi phí thu hút có thể cao hơn nhiều.',
      d:'Vẫn còn tiền thuê kho, và ai sẽ đóng gói 250 đơn?'} },
  { type:'calc', stem:'Giá bán 250.000đ; giá vốn 100.000đ; ship shop chịu 20.000đ; phí sàn 12% giá bán; đóng gói 5.000đ; quảng cáo 60.000đ mỗi đơn. Đóng góp mỗi đơn là bao nhiêu đồng?',
    unit:'đ', ans:35000, tol:1, wrong:[[95000,'QUEN_TRU_CHI_PHI_QC'],[65000,'QUEN_CHI_PHI_BIEN_DOI'],[150000,'NHAM_GIA_VON']], errors:['QUEN_TRU_CHI_PHI_QC','QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Phí sàn = 250.000 × 12% = 30.000đ.','Tổng chi phí theo đơn = 100.000 + 20.000 + 30.000 + 5.000 + 60.000 = 215.000đ.','Đóng góp = 250.000 − 215.000 = <b>35.000đ</b>.'] },
  { type:'calc', stem:'Mỗi đơn đóng góp 35.000đ. Chi phí cố định (kho + lương) là 14.000.000đ mỗi tháng. Shop cần bao nhiêu đơn mỗi tháng để hoà vốn?',
    unit:'đơn', ans:400, tol:0.5, wrong:[[147.4,'QUEN_TRU_CHI_PHI_QC'],[93.3,'NHAM_GIA_VON']], errors:['QUEN_CHI_PHI_CO_DINH'],
    steps:['Hoà vốn = chi phí cố định ÷ đóng góp mỗi đơn.','14.000.000 ÷ 35.000 = <b>400 đơn</b>.'] },
  { type:'mcq', stem:'Sàn tổ chức ngày hội, yêu cầu shop giảm thêm 10% giá bán. Với cấu trúc chi phí trên, điều gì xảy ra với đóng góp mỗi đơn?',
    options:[{k:'a',t:'Giảm 25.000đ nhưng phí sàn cũng giảm theo, nên chỉ mất chút ít'},{k:'b',t:'Giảm đúng 10%, từ 35.000đ xuống khoảng 31.500đ'},
             {k:'c',t:'Tăng lên vì ngày hội có nhiều đơn hơn nên mỗi đơn tốt hơn'},{k:'d',t:'Giảm còn khoảng 13.000đ, mất gần hai phần ba'}],
    answer:'d', why:{a:'Phí sàn giảm 3.000đ, nhưng giá giảm 25.000đ; mất ròng 22.000đ trên 35.000đ là không phải chút ít.',
      b:'Giảm giá đánh thẳng vào số tuyệt đối 25.000đ, không phải 10% của phần đóng góp.',
      c:'Nhiều đơn hơn không làm mỗi đơn lời hơn.',
      d:'Đúng. Giá 225.000đ, phí sàn 27.000đ → đóng góp 225.000 − 212.000 = 13.000đ.'} },
  { type:'mcq', stem:'Một chủ shop nói: "Mỗi đơn lời 150.000đ, 100 đơn là đủ trả 14 triệu." Lỗi nằm ở đâu?',
    options:[{k:'a',t:'Lấy giá bán trừ giá vốn, bỏ qua ship, phí sàn, đóng gói và quảng cáo'},{k:'b',t:'Chỉ sai ở chỗ quên tính thuế, còn cách tính đóng góp mỗi đơn thì đã đúng'},
             {k:'c',t:'Tính đúng, chỉ là 14 triệu nên được chia cho 30 ngày trước'},{k:'d',t:'Sai vì sàn giữ tiền 7 ngày trước khi chuyển về tài khoản'}],
    answer:'a', why:{a:'Đúng. 150.000đ là chênh lệch giá bán − giá vốn, chưa phải phần đóng góp.',
      b:'Thuế có thể phải tính, nhưng sai lớn nhất là bỏ qua 115.000đ chi phí theo đơn.',
      c:'Chia theo ngày không đổi kết quả tháng.',
      d:'Giữ tiền ảnh hưởng dòng tiền, không ảnh hưởng lời lỗ mỗi đơn.'} },
  { type:'mcq', stem:'Cách nào tăng đóng góp mỗi đơn mà không phải đổi sản phẩm?',
    options:[{k:'a',t:'Tăng chi quảng cáo cho mỗi đơn'},{k:'b',t:'Giảm giá sâu để lên top tìm kiếm của sàn'},
             {k:'c',t:'Bán combo 2–3 món để chi phí theo đơn chia cho giá trị lớn hơn'},{k:'d',t:'Chuyển ship sang loại nhanh hơn để khách hài lòng hơn'}],
    answer:'c', why:{a:'Thêm quảng cáo là tăng một dòng chi phí mỗi đơn.',
      b:'Giảm giá sâu cắt thẳng vào đóng góp, có thể thành âm.',
      c:'Đúng. Ship, đóng gói và một phần quảng cáo gần như không tăng khi đơn to hơn.',
      d:'Ship nhanh thường đắt hơn, làm đóng góp giảm nếu shop chịu phí.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:dl02-07', skill:'measure', read:'6 phút', t:'Nhân đôi ngân sách thì CAC có giữ nguyên không?',
  situation:'Một thương hiệu nước ép lạnh ở TP.HCM chi 20 triệu mỗi tháng trên Facebook và có 200 khách mới. Thấy CAC 100.000đ, sếp duyệt tăng lên 40 triệu. Tháng sau có 300 khách mới. Báo cáo ghi CAC 133.000đ, "vẫn thấp hơn LTV lãi gộp 180.000đ". Cả đội vui mừng.',
  concept:{ name:'CAC biên — giá của khách thêm vào',
    body:'Khi tăng chi, nền tảng phải tìm người ở xa dần nhóm dễ mua nhất: kém quan tâm hơn, ở xa khu giao hàng hơn, đã thấy quảng cáo nhiều lần. Vì vậy khách thêm vào thường đắt hơn khách cũ. <b>CAC biên = chi phí tăng thêm ÷ khách mới tăng thêm</b>. CAC bình quân trộn khách rẻ ở mức chi cũ với khách đắt ở mức chi mới, nên che mất việc phần tiền thêm có còn lời không. Quyết định chi thêm phải dựa trên CAC biên.' },
  example:'Tiền thêm: 40 − 20 = 20 triệu. Khách thêm: 300 − 200 = 100. CAC biên = 20 triệu ÷ 100 = 200.000đ, cao hơn LTV lãi gộp 180.000đ. Nghĩa là 20 triệu tăng thêm đang lỗ khoảng 2 triệu, dù CAC bình quân 133.000đ vẫn trông an toàn. Mức chi hợp lý nằm đâu đó giữa 20 và 40 triệu — cần thử các nấc nhỏ hơn.',
  takeaway:'Khi tăng ngân sách, hỏi khách thêm vào tốn bao nhiêu, không phải khách trung bình tốn bao nhiêu.',
  apply:'Nhớ lại một lần bạn hoặc công ty tăng ngân sách quảng cáo. Nói trong 60 giây: CAC biên của phần tăng thêm là bao nhiêu, và nó có dưới LTV lãi gộp không.',
  mistakes:['Nhìn CAC bình quân sau khi tăng chi và kết luận phần tiền thêm vẫn lời.','Tăng ngân sách một bước lớn thay vì tăng từng nấc để thấy CAC biên thay đổi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: ngân sách tăng gấp đôi, khách mới tăng từ 200 lên 300. Khách thêm vào tốn bao nhiêu mỗi người?',
    options:[{k:'a',t:'100.000đ, vì nền tảng giữ nguyên giá cho mỗi khách mới như tháng trước'},{k:'b',t:'133.000đ, đúng như CAC bình quân trên báo cáo'},
             {k:'c',t:'200.000đ, vì 20 triệu thêm chỉ mang về 100 khách'},{k:'d',t:'Không tính được nếu không biết khách nào đến từ tiền nào'}],
    answer:'c', why:{a:'Nếu giữ giá thì 40 triệu phải ra 400 khách, không phải 300.',
      b:'133.000đ trộn cả khách rẻ ở mức chi cũ.',
      c:'Đúng. 20 triệu ÷ 100 khách thêm = 200.000đ.',
      d:'Không cần gắn từng khách; so hai mức chi là đủ ước CAC biên.'} },
  { type:'mcq', stem:'Sếp hỏi có giữ mức 40 triệu không. Bạn đề xuất gì?',
    options:[{k:'a',t:'Giữ 40 triệu, vì CAC bình quân 133.000đ vẫn dưới LTV 180.000đ nên cả khoản chi vẫn đang có lời'},{k:'b',t:'Lùi về khoảng 28–30 triệu, đo CAC biên từng nấc'},
             {k:'c',t:'Tăng lên 60 triệu để tận dụng đà tăng khách'},{k:'d',t:'Quay về 20 triệu và không bao giờ tăng ngân sách nữa'}],
    answer:'b', why:{a:'Bình quân dưới LTV không có nghĩa phần tăng thêm có lời; phần đó đang lỗ.',
      b:'Đúng. Tìm nấc mà CAC biên vẫn dưới LTV lãi gộp.',
      c:'Nấc tiếp theo gần như chắc chắn còn đắt hơn 200.000đ.',
      d:'Có thể có nấc giữa vẫn lời; bỏ hẳn là bỏ khách có lời.'} },
  { type:'calc', stem:'Chi 20.000.000đ → 200 khách mới. Tăng lên 40.000.000đ → 300 khách mới. CAC biên của phần tiền tăng thêm là bao nhiêu đồng?',
    unit:'đ', ans:200000, tol:1, wrong:[[133333,'SAI_MAU_SO'],[100000,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Chi phí tăng thêm = 40.000.000 − 20.000.000 = 20.000.000đ.','Khách tăng thêm = 300 − 200 = 100.','CAC biên = 20.000.000 ÷ 100 = <b>200.000đ</b>.'] },
  { type:'mcq', stem:'Vì sao khách thêm vào thường đắt hơn khi tăng ngân sách trên cùng một kênh?',
    options:[{k:'a',t:'Vì nền tảng cố tình tăng giá với tài khoản chi nhiều để thu thêm tiền'},{k:'b',t:'Vì nội dung quảng cáo bị cũ đi, chỉ cần đổi hình là CAC trở về mức cũ ngay'},
             {k:'c',t:'Vì chi nhiều hơn thì đội ngũ làm việc kém tập trung hơn'},{k:'d',t:'Vì nhóm dễ mua nhất đã được chạm tới, phải với ra nhóm kém quan tâm hơn'}],
    answer:'d', why:{a:'Không cần giả định âm mưu; bản chất tệp người là đủ giải thích.',
      b:'Nội dung mỏi có góp phần, nhưng đổi hình không đưa những người kém quan tâm trở nên dễ mua.',
      c:'Không có dữ kiện về năng suất đội.',
      d:'Đúng. Càng chi nhiều càng phải chạm người ở xa nhóm lý tưởng.'} },
  { type:'mcq', stem:'Một shop tăng từ 10 triệu lên 12 triệu, khách mới từ 100 lên 118. LTV lãi gộp 150.000đ. Kết luận nào đúng?',
    options:[{k:'a',t:'CAC biên khoảng 111.000đ, vẫn dưới LTV — phần tăng thêm còn lời'},{k:'b',t:'CAC bình quân tăng từ 100.000đ lên 101.700đ nên phải dừng ngay'},
             {k:'c',t:'Tăng 18 khách là quá ít, kênh đã bão hoà'},{k:'d',t:'Không kết luận được nếu chưa chạy thêm ít nhất 6 tháng'}],
    answer:'a', why:{a:'Đúng. 2 triệu ÷ 18 ≈ 111.000đ, dưới 150.000đ.',
      b:'CAC bình quân nhích lên là bình thường; cái cần xem là CAC biên so với LTV.',
      c:'18 khách với giá 111.000đ vẫn có lời; ít không có nghĩa là lỗ.',
      d:'Cần kiểm tra lại, nhưng một tháng đã đủ để có ước lượng ban đầu.'} },
  { type:'mcq', stem:'Ngoài tăng chi trên cùng kênh, cách nào giúp mở rộng quy mô mà CAC biên tăng chậm hơn?',
    options:[{k:'a',t:'Nhồi thêm tiền vào đúng một nhóm quảng cáo đang chạy tốt nhất'},{k:'b',t:'Mở tệp mới: kênh mới, khu vực mới, nội dung cho nhóm khách mới'},
             {k:'c',t:'Giảm giá sâu cho mọi khách mới để tăng tỉ lệ chuyển đổi trên trang sản phẩm'},{k:'d',t:'Tắt đo lường để đội bớt áp lực phải đạt CAC'}],
    answer:'b', why:{a:'Dồn vào một nhóm là cách nhanh nhất làm nhóm đó bão hoà.',
      b:'Đúng. Tệp mới có những người dễ mua chưa được chạm tới.',
      c:'Giảm giá có thể làm CAC thấp đi nhưng cắt vào lãi mỗi khách, LTV giảm theo.',
      d:'Không đo thì không biết CAC biên, chỉ làm vấn đề vô hình.'} },
  { type:'mcq', stem:'Câu nào mô tả đúng quan hệ giữa CAC bình quân và CAC biên khi tăng ngân sách?',
    options:[{k:'a',t:'Luôn bằng nhau nếu chạy trên cùng một nền tảng'},{k:'b',t:'CAC bình quân luôn cao hơn CAC biên vì bao gồm nhiều khách hơn'},
             {k:'c',t:'CAC biên thường cao hơn; bình quân tăng chậm nên che phần lỗ'},{k:'d',t:'CAC biên chỉ quan trọng với doanh nghiệp lớn'}],
    answer:'c', why:{a:'Chúng chỉ bằng nhau khi khách thêm vào có giá giống khách cũ, hiếm khi xảy ra.',
      b:'Ngược lại: khách thêm vào thường đắt hơn trung bình.',
      c:'Đúng. Bình quân bị khách rẻ cũ kéo xuống, nên phần tiền thêm có thể lỗ mà không thấy.',
      d:'Shop nhỏ tăng từ 10 lên 20 triệu cũng gặp đúng hiện tượng này.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:dl02-08', skill:'measure', read:'7 phút', t:'Khi nào nên chấp nhận CAC 1,2 triệu cho một khách?',
  situation:'Một chuỗi phòng tập yoga ở Hà Nội có CAC 1,2 triệu cho một hội viên — cao gấp ba shop mỹ phẩm bên cạnh. Mỗi hội viên đóng gói tháng, còn lại 300.000đ lãi gộp mỗi tháng, ở lại trung bình 12 tháng. Cứ hai hội viên thì có một người rủ thêm được một bạn tới đăng ký. Chuỗi có đủ vốn để chờ 6 tháng.',
  concept:{ name:'CAC cao vẫn có thể đáng',
    body:'CAC không cao hay thấp một mình; nó cao hay thấp <b>so với</b> giá trị khách và khả năng chờ. CAC cao có thể chấp nhận khi: (1) LTV lãi gộp đủ lớn để tỉ lệ vẫn lành mạnh; (2) thời gian hoàn vốn nằm trong khả năng vốn; (3) mỗi khách kéo thêm khách qua giới thiệu, làm <b>CAC hiệu dụng</b> thấp hơn; (4) khách này mở ra giá trị khác như bán kèm. Ngược lại, CAC thấp mà khách rời sau một lần mua có thể còn tệ hơn.' },
  example:'LTV lãi gộp = 300.000 × 12 = 3,6 triệu; tỉ lệ 3,6 ÷ 1,2 = 3. Hoàn vốn = 1,2 triệu ÷ 300.000 = 4 tháng, trong ngưỡng 6 tháng. Tính giới thiệu: mỗi hội viên trả tiền kéo thêm 0,5 người, nên 1,2 triệu có được 1,5 hội viên → CAC hiệu dụng 800.000đ. CAC cao gấp ba shop bên cạnh, nhưng đây là khoản đáng chi.',
  takeaway:'CAC cao là chấp nhận được khi lãi mỗi khách, thời gian hoàn vốn và giới thiệu cùng đứng về phía bạn.',
  apply:'Chọn một ngành có CAC cao (phòng tập, giáo dục, nội thất). Nói trong 60 giây bốn điều kiện khiến CAC cao đó vẫn đáng, và điều kiện nào dễ gãy nhất.',
  mistakes:['So CAC giữa hai ngành khác nhau và kết luận ngành CAC cao là kém hiệu quả.','Cộng khoản giới thiệu vào khi chưa đo được tỉ lệ giới thiệu thật.'],
  q:[
  { type:'mcq', stem:'Đoán trước: CAC 1,2 triệu của phòng tập cao gấp ba shop mỹ phẩm. Phòng tập có đang tiêu tiền kém hiệu quả không?',
    options:[{k:'a',t:'Có, vì CAC càng thấp càng hiệu quả'},{k:'b',t:'Có, vì ngành thể thao thường có biên lãi thấp hơn ngành mỹ phẩm'},
             {k:'c',t:'Không, vì dịch vụ không cần tính CAC'},{k:'d',t:'Chưa kết luận được — phải so CAC với giá trị và vòng đời hội viên'}],
    answer:'d', why:{a:'Một khách ở lại 12 tháng có giá trị rất khác khách mua một thỏi son.',
      b:'Không có dữ kiện biên lãi ngành; và kể cả vậy vẫn phải so với LTV.',
      c:'Dịch vụ vẫn tốn tiền thu hút, vẫn cần CAC.',
      d:'Đúng. CAC chỉ có nghĩa khi đặt cạnh LTV và thời gian hoàn vốn.'} },
  { type:'mcq', stem:'Một đối tác đề nghị kênh mới với CAC 1,5 triệu, hội viên từ kênh này ở lại trung bình 12 tháng như cũ. Vốn chỉ đủ chờ 6 tháng. Bạn chọn gì?',
    options:[{k:'a',t:'Thử quy mô nhỏ: hoàn vốn 5 tháng vẫn trong ngưỡng, nhưng đo giữ chân thật'},{k:'b',t:'Từ chối vì CAC 1,5 triệu cao hơn mức 1,2 triệu hiện tại nên chắc chắn kém hơn kênh đang chạy'},
             {k:'c',t:'Dồn hết ngân sách sang vì kênh mới có thể mang khách chất lượng hơn'},{k:'d',t:'Chấp nhận ngay vì tỉ lệ LTV/CAC vẫn là 2,4, trên mức 2'}],
    answer:'a', why:{a:'Đúng. 1,5 triệu ÷ 300.000 = 5 tháng, sát ngưỡng vốn; thử nhỏ và kiểm tra giả định 12 tháng.',
      b:'Cao hơn không có nghĩa là lỗ; 5 tháng hoàn vốn và tỉ lệ 2,4 vẫn có thể chấp nhận.',
      c:'"Có thể chất lượng hơn" chưa được đo; dồn hết là cược cả vốn.',
      d:'Tỉ lệ ổn, nhưng hoàn vốn 5 tháng sát ngưỡng 6 — cần thử trước khi chấp nhận toàn bộ.'} },
  { type:'calc', stem:'CAC 1.200.000đ. Cứ mỗi hội viên trả tiền thì trung bình kéo thêm 0,5 hội viên qua giới thiệu (không tốn thêm chi phí). CAC hiệu dụng mỗi hội viên là bao nhiêu đồng?',
    unit:'đ', ans:800000, tol:1, wrong:[[1200000,'QUEN_TI_LE_GIOI_THIEU'],[600000,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_GIOI_THIEU'],
    steps:['1.200.000đ có được 1 + 0,5 = 1,5 hội viên.','CAC hiệu dụng = 1.200.000 ÷ 1,5 = <b>800.000đ</b>.'] },
  { type:'mcq', stem:'Điều kiện nào dễ gãy nhất khiến CAC 1,2 triệu từ đáng thành không đáng?',
    options:[{k:'a',t:'Giá gói tăng thêm 10% vào năm sau do chi phí thuê mặt bằng'},{k:'b',t:'Hội viên ở lại trung bình 4 tháng thay vì 12 tháng'},
             {k:'c',t:'Shop mỹ phẩm bên cạnh giảm CAC của họ xuống thấp hơn nữa'},{k:'d',t:'Phòng tập mở thêm một lớp buổi sáng'}],
    answer:'b', why:{a:'Tăng giá làm lãi mỗi tháng cao hơn, có lợi cho việc hoàn vốn.',
      b:'Đúng. LTV lãi gộp còn 1,2 triệu, bằng CAC — mọi khoản lời biến mất.',
      c:'CAC của ngành khác không ảnh hưởng tới kinh tế của phòng tập.',
      d:'Thêm lớp là chuyện vận hành, không phá vỡ phép tính.'} },
  { type:'mcq', stem:'Một trung tâm tiếng Anh có CAC 3 triệu cho một học viên khoá 6 tháng, lãi gộp khoá 2 triệu. Nhưng 40% học viên đăng ký tiếp khoá sau với cùng mức lãi. Đọc thế nào?',
    options:[{k:'a',t:'Lỗ, vì lãi một khoá thấp hơn CAC nên khoản tái đăng ký không bù nổi'},{k:'b',t:'Lời lớn, vì 40% học viên đăng ký tiếp chứng tỏ chất lượng tốt'},
             {k:'c',t:'Lãi kỳ vọng 2,8 triệu vẫn dưới CAC — cần giảm CAC hoặc tăng tái đăng ký'},{k:'d',t:'Không liên quan, vì giáo dục nên đo bằng kết quả học tập'}],
    answer:'c', why:{a:'Tái đăng ký có bù một phần; kết luận "không thể" bỏ qua con số 40%.',
      b:'Chất lượng tốt nhưng phép tính vẫn chưa có lời.',
      c:'Đúng. 2 triệu + 40% × 2 triệu = 2,8 triệu, vẫn thiếu 200.000đ so với CAC.',
      d:'Kết quả học tập quan trọng, nhưng trung tâm vẫn cần có lời để tồn tại.'} },
  { type:'mcq', stem:'Một bạn đề xuất trừ giá trị giới thiệu vào CAC dù chưa từng đo tỉ lệ giới thiệu, chỉ "ước chừng mỗi người rủ một bạn". Rủi ro là gì?',
    options:[{k:'a',t:'CAC hiệu dụng bị đánh giá thấp giả tạo, dẫn tới chi quá tay'},{k:'b',t:'Chẳng sao vì giới thiệu luôn tồn tại trong mọi ngành'},
             {k:'c',t:'CAC hiệu dụng sẽ bị cao hơn thật, khiến chuỗi phòng tập bỏ lỡ những kênh đang có lời'},{k:'d',t:'Chỉ sai về mặt kế toán, không ảnh hưởng quyết định'}],
    answer:'a', why:{a:'Đúng. Giả định một người rủ một bạn làm CAC giảm một nửa trên giấy.',
      b:'Giới thiệu có thật nhưng mức độ khác nhau rất xa; phải đo.',
      c:'Ngược lại: cộng giới thiệu giả định làm CAC thấp đi, không cao lên.',
      d:'Con số này chính là căn cứ quyết định ngân sách.'} },
  { type:'mcq', stem:'Trường hợp nào CAC THẤP lại là dấu hiệu đáng lo?',
    options:[{k:'a',t:'Khi CAC thấp nhờ nhắm đúng tệp khách'},{k:'b',t:'Khi CAC thấp hơn đối thủ nhờ nội dung được chia sẻ tự nhiên'},
             {k:'c',t:'Khi CAC thấp đi kèm LTV cao và thời gian hoàn vốn ngắn'},{k:'d',t:'Khi CAC thấp nhờ khuyến mãi sâu, khách mua một lần rồi rời'}],
    answer:'d', why:{a:'Nhắm đúng tệp là lý do tốt cho CAC thấp.',
      b:'Lan truyền tự nhiên là lợi thế thật.',
      c:'Đây là trạng thái lý tưởng, không đáng lo.',
      d:'Đúng. Khách săn khuyến mãi làm CAC đẹp nhưng LTV gần như bằng không.'} }
  ] }

]});
